def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    if n >= 99:
        return 'D'
    last_opp = history[-1][1]
    if n < 8:
        return 'C' if last_opp == 'C' else 'D'

    opp_c = sum(1 for a, b in history if b == 'C')
    my_c = sum(1 for a, b in history if a == 'C')

    d_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        d_streak += 1
        i -= 1

    if opp_c == n and n >= 20 and n <= 96:
        if rng.random() < 0.02:
            return 'D'

    if d_streak == 1 and last_opp == 'C' and opp_c * 100 >= n * 95:
        return 'D'
    if d_streak >= 2 and last_opp == 'C':
        return 'D'
    if d_streak >= 1 and last_opp == 'D' and opp_c * 100 > n * 70:
        return 'C'

    if opp_c >= 95:
        return 'C'
    if opp_c <= 3 and n >= 20:
        return 'D'

    recent = history[-12:]
    opp_recent_c = sum(1 for a, b in recent if b == 'C')

    if opp_recent_c == 0:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    if opp_recent_c >= 11:
        return 'C'

    perceived_forgiveness = opp_c / n
    if perceived_forgiveness > 0.65:
        if last_opp == 'D' and history[-2][1] == 'C' and rng.random() < 0.7:
            return 'D'
        return 'C'

    if my_c / n > 0.75 and last_opp == 'D':
        return 'D'

    if n > 60 and opp_c > 35 and my_c < 30:
        return 'C'

    if last_opp == 'D':
        if rng.random() < 0.15 + 0.25 * (opp_recent_c / 12):
            return 'C'
        return 'D'

    if n % 10 == 9 and my_c > opp_c + 10:
        return 'D'

    return 'C'
